@Override // com.macrovideo.v380.fragments.BaseFragment
protected void handleMessage(Message message) {
    AlarmConfigInfo alarmConfigInfo;
    super.handleMessage(message);
    this.mActivity.dismissLoadingDialog();
    int i = message.what;
    if (i == 1) {
        this.mActivity.dismissLoadingDialog();
        if (message.arg1 == 1001) {
            this.mActivity.showToast(getString(R.string.str_format_sdcard_succeefully), 1);
            if (GlobalDefines.sDeviceConfigure == null || GlobalDefines.sDeviceConfigure.getmRecordInfo() == null) {
                return;
            }
            GlobalDefines.sDeviceConfigure.getmRecordInfo().setnRecordStat(1);
        }
        this.mActivity.showToast(getString(R.string.str_format_sdcard_failed), 0);
        return;
    }
